export type ID = string;

export interface User {
  id: ID;
  name: string;
  email: string;
}

export interface Project {
  id: ID;
  name: string;
  description?: string;
  members: ID[];
}

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
  id: ID;
  title: string;
  description?: string;
  status: TaskStatus;
  assignee?: ID | null;
  projectId: ID;
}

export interface Comment {
  id: ID;
  taskId: ID;
  authorId: ID;
  body: string;
  createdAt: string; // ISO
}

export interface Notification {
  id: ID;
  userId: ID;
  message: string;
  read: boolean;
  createdAt: string;
}

type Callback = (payload: any) => void;

export class EventBus {
  private subscribers: Map<string, Callback[]> = new Map();

  subscribe(eventName: string, cb: Callback) {
    const list = this.subscribers.get(eventName) || [];
    list.push(cb);
    this.subscribers.set(eventName, list);
    return () => {
      const cur = this.subscribers.get(eventName) || [];
      this.subscribers.set(
        eventName,
        cur.filter((c) => c !== cb)
      );
    };
  }

  publish(eventName: string, payload: any) {
    const list = this.subscribers.get(eventName) || [];
    for (const cb of list) {
      // Call safely
      try {
        cb(payload);
      } catch (err) {
        // swallow
        console.error('Event handler error for', eventName, err);
      }
    }
  }
}

import { User, ID } from '../types';
import { randomUUID } from 'crypto';

export class UserService {
  private users: Map<ID, User> = new Map();

  createUser(name: string, email: string): User {
    const id = randomUUID();
    const user: User = { id, name, email };
    this.users.set(id, user);
    return user;
  }

  getUser(id: ID): User | undefined {
    return this.users.get(id);
  }

  listUsers(): User[] {
    return Array.from(this.users.values());
  }

  updateUser(id: ID, data: Partial<Omit<User, 'id'>>): User | undefined {
    const u = this.users.get(id);
    if (!u) return undefined;
    const updated = { ...u, ...data };
    this.users.set(id, updated);
    return updated;
  }

  deleteUser(id: ID): boolean {
    return this.users.delete(id);
  }
}

import { Project, ID } from '../types';
import { randomUUID } from 'crypto';

export class ProjectService {
  private projects: Map<ID, Project> = new Map();

  createProject(name: string, description?: string): Project {
    const id = randomUUID();
    const p: Project = { id, name, description, members: [] };
    this.projects.set(id, p);
    return p;
  }

  getProject(id: ID): Project | undefined {
    return this.projects.get(id);
  }

  listProjects(): Project[] {
    return Array.from(this.projects.values());
  }

  updateProject(id: ID, data: Partial<Omit<Project, 'id' | 'members'>>) {
    const p = this.projects.get(id);
    if (!p) return undefined;
    const updated = { ...p, ...data } as Project;
    this.projects.set(id, updated);
    return updated;
  }

  deleteProject(id: ID) {
    return this.projects.delete(id);
  }

  addMember(projectId: ID, userId: ID) {
    const p = this.projects.get(projectId);
    if (!p) return false;
    if (!p.members.includes(userId)) p.members.push(userId);
    return true;
  }

  removeMember(projectId: ID, userId: ID) {
    const p = this.projects.get(projectId);
    if (!p) return false;
    p.members = p.members.filter((m) => m !== userId);
    this.projects.set(projectId, p);
    return true;
  }
}

import { Task, ID, TaskStatus } from '../types';
import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export class TaskService {
  private tasks: Map<ID, Task> = new Map();
  private bus: EventBus;

  constructor(bus: EventBus) {
    this.bus = bus;
  }

  createTask(title: string, projectId: ID, description?: string): Task {
    const id = randomUUID();
    const t: Task = { id, title, description, status: 'todo', assignee: null, projectId };
    this.tasks.set(id, t);
    this.bus.publish('task.created', t);
    return t;
  }

  getTask(id: ID): Task | undefined {
    return this.tasks.get(id);
  }

  listTasks(filter?: { projectId?: ID }): Task[] {
    let arr = Array.from(this.tasks.values());
    if (filter?.projectId) arr = arr.filter((t) => t.projectId === filter.projectId);
    return arr;
  }

  updateTask(id: ID, data: Partial<Omit<Task, 'id' | 'projectId'>>) {
    const t = this.tasks.get(id);
    if (!t) return undefined;
    const updated = { ...t, ...data } as Task;
    this.tasks.set(id, updated);
    this.bus.publish('task.updated', updated);
    return updated;
  }

  deleteTask(id: ID) {
    const t = this.tasks.get(id);
    if (!t) return false;
    this.tasks.delete(id);
    this.bus.publish('task.deleted', { id });
    return true;
  }

  setStatus(id: ID, status: TaskStatus) {
    const t = this.tasks.get(id);
    if (!t) return { ok: false, reason: 'not found' };
    const order: TaskStatus[] = ['todo', 'in-progress', 'done'];
    const curIdx = order.indexOf(t.status);
    const newIdx = order.indexOf(status);
    if (newIdx === -1) return { ok: false, reason: 'invalid status' };
    if (newIdx < curIdx) return { ok: false, reason: 'invalid transition' };
    t.status = status;
    this.tasks.set(id, t);
    this.bus.publish('task.status_changed', t);
    return { ok: true, task: t };
  }

  assign(id: ID, userId: ID) {
    const t = this.tasks.get(id);
    if (!t) return { ok: false, reason: 'not found' };
    t.assignee = userId;
    this.tasks.set(id, t);
    this.bus.publish('task.assigned', t);
    return { ok: true, task: t };
  }
}

import { Comment, ID } from '../types';
import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export class CommentService {
  private comments: Map<ID, Comment> = new Map();
  private bus: EventBus;

  constructor(bus: EventBus) {
    this.bus = bus;
  }

  addComment(taskId: ID, authorId: ID, body: string): Comment {
    const id = randomUUID();
    const now = new Date().toISOString();
    const c: Comment = { id, taskId, authorId, body, createdAt: now };
    this.comments.set(id, c);
    this.bus.publish('comment.added', c);
    return c;
  }

  getComment(id: ID): Comment | undefined {
    return this.comments.get(id);
  }

  listComments(filter?: { taskId?: ID }): Comment[] {
    let arr = Array.from(this.comments.values());
    if (filter?.taskId) arr = arr.filter((c) => c.taskId === filter.taskId);
    return arr;
  }

  deleteComment(id: ID) {
    return this.comments.delete(id);
  }
}

import { Notification, ID } from '../types';
import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export class NotificationService {
  private notifications: Map<ID, Notification> = new Map();
  private bus: EventBus;

  constructor(bus: EventBus) {
    this.bus = bus;
    this.setupSubscriptions();
  }

  private setupSubscriptions() {
    this.bus.subscribe('task.assigned', (payload) => {
      const task = payload as any;
      if (task.assignee) {
        this.createNotification(task.assignee, `You were assigned task: ${task.title}`);
      }
    });

    this.bus.subscribe('comment.added', (payload) => {
      const comment = payload as any;
      // payload includes taskId and authorId and body
      // We can't access task assignee directly (per rules), so expect payload to include assignee? But per spec comment service publishes only comment. The router orchestrates lookups. However notification service should create notification for task's assignee when comment added. To respect data ownership, the comment.added payload should include task snapshot. We'll assume comment.added payload contains { comment, task } when published by API.
      const maybeTask = comment.task as any;
      const comm = comment.comment as any;
      if (maybeTask && maybeTask.assignee) {
        this.createNotification(maybeTask.assignee, `New comment on task ${maybeTask.title}: ${comm.body}`);
      }
    });

    this.bus.subscribe('task.status_changed', (payload) => {
      const task = payload as any;
      if (task.assignee) {
        this.createNotification(task.assignee, `Status changed for task ${task.title} -> ${task.status}`);
      }
    });
  }

  private createNotification(userId: ID, message: string) {
    const id = randomUUID();
    const n: Notification = { id, userId, message, read: false, createdAt: new Date().toISOString() };
    this.notifications.set(id, n);
  }

  listNotifications(filter?: { userId?: ID }) {
    let arr = Array.from(this.notifications.values());
    if (filter?.userId) arr = arr.filter((n) => n.userId === filter.userId);
    return arr;
  }

  markRead(id: ID) {
    const n = this.notifications.get(id);
    if (!n) return false;
    n.read = true;
    this.notifications.set(id, n);
    return true;
  }
}

import { createServer, IncomingMessage, ServerResponse } from 'http';
import { parse as parseUrl } from 'url';
import { EventBus } from './event-bus';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';

function json(res: ServerResponse, status: number, body: any) {
  const s = JSON.stringify(body);
  res.writeHead(status, { 'Content-Type': 'application/json' });
  res.end(s);
}

function notFound(res: ServerResponse) {
  json(res, 404, { error: 'not found' });
}

export class ApiServer {
  private bus: EventBus;
  private userSvc: UserService;
  private projectSvc: ProjectService;
  private taskSvc: TaskService;
  private commentSvc: CommentService;
  private notificationSvc: NotificationService;

  constructor() {
    this.bus = new EventBus();
    this.userSvc = new UserService();
    this.projectSvc = new ProjectService();
    this.taskSvc = new TaskService(this.bus);
    this.commentSvc = new CommentService(this.bus);
    this.notificationSvc = new NotificationService(this.bus);
  }

  handler = async (req: IncomingMessage, res: ServerResponse) => {
    const url = parseUrl(req.url || '', true);
    const path = url.pathname || '/';
    const method = (req.method || 'GET').toUpperCase();

    // simple body parse
    const body = await new Promise<any>((resolve) => {
      let data = '';
      req.on('data', (chunk) => (data += chunk));
      req.on('end', () => {
        if (!data) return resolve(undefined);
        try {
          resolve(JSON.parse(data));
        } catch (err) {
          resolve(undefined);
        }
      });
    });

    // Routing
    try {
      // Users
      if (path === '/users' && method === 'GET') return json(res, 200, this.userSvc.listUsers());
      if (path === '/users' && method === 'POST') {
        const { name, email } = body || {};
        if (!name || !email) return json(res, 400, { error: 'name and email required' });
        const u = this.userSvc.createUser(name, email);
        return json(res, 201, u);
      }

      const userIdMatch = path.match(/^\/users\/([^/]+)$/);
      if (userIdMatch) {
        const id = userIdMatch[1];
        if (method === 'GET') {
          const u = this.userSvc.getUser(id);
          if (!u) return notFound(res);
          return json(res, 200, u);
        }
        if (method === 'PUT') {
          const updated = this.userSvc.updateUser(id, body || {});
          if (!updated) return notFound(res);
          return json(res, 200, updated);
        }
        if (method === 'DELETE') {
          const ok = this.userSvc.deleteUser(id);
          if (!ok) return notFound(res);
          return json(res, 204, '');
        }
      }

      // Projects
      if (path === '/projects' && method === 'GET') return json(res, 200, this.projectSvc.listProjects());
      if (path === '/projects' && method === 'POST') {
        const { name, description } = body || {};
        if (!name) return json(res, 400, { error: 'name required' });
        const p = this.projectSvc.createProject(name, description);
        return json(res, 201, p);
      }

      const projectMatch = path.match(/^\/projects\/([^/]+)$/);
      if (projectMatch) {
        const id = projectMatch[1];
        if (method === 'GET') {
          const p = this.projectSvc.getProject(id);
          if (!p) return notFound(res);
          return json(res, 200, p);
        }
        if (method === 'PUT') {
          const updated = this.projectSvc.updateProject(id, body || {});
          if (!updated) return notFound(res);
          return json(res, 200, updated);
        }
        if (method === 'DELETE') {
          const ok = this.projectSvc.deleteProject(id);
          if (!ok) return notFound(res);
          return json(res, 204, '');
        }
      }

      const projectMemberMatch = path.match(/^\/projects\/([^/]+)\/members$/);
      if (projectMemberMatch) {
        const id = projectMemberMatch[1];
        if (method === 'POST') {
          const { userId } = body || {};
          if (!userId) return json(res, 400, { error: 'userId required' });
          const ok = this.projectSvc.addMember(id, userId);
          if (!ok) return notFound(res);
          return json(res, 200, { ok: true });
        }
        if (method === 'DELETE') {
          const { userId } = body || {};
          if (!userId) return json(res, 400, { error: 'userId required' });
          const ok = this.projectSvc.removeMember(id, userId);
          if (!ok) return notFound(res);
          return json(res, 200, { ok: true });
        }
      }

      // Tasks
      if (path === '/tasks' && method === 'GET') {
        const projectId = url.query['projectId'] as string | undefined;
        return json(res, 200, this.taskSvc.listTasks(projectId ? { projectId } : undefined));
      }
      if (path === '/tasks' && method === 'POST') {
        const { title, description, projectId } = body || {};
        if (!title || !projectId) return json(res, 400, { error: 'title and projectId required' });
        const t = this.taskSvc.createTask(title, projectId, description);
        return json(res, 201, t);
      }

      const taskMatch = path.match(/^\/tasks\/([^/]+)$/);
      if (taskMatch) {
        const id = taskMatch[1];
        if (method === 'GET') {
          const t = this.taskSvc.getTask(id);
          if (!t) return notFound(res);
          return json(res, 200, t);
        }
        if (method === 'PUT') {
          const updated = this.taskSvc.updateTask(id, body || {});
          if (!updated) return notFound(res);
          return json(res, 200, updated);
        }
        if (method === 'DELETE') {
          const ok = this.taskSvc.deleteTask(id);
          if (!ok) return notFound(res);
          return json(res, 204, '');
        }
      }

      const taskStatusMatch = path.match(/^\/tasks\/([^/]+)\/status$/);
      if (taskStatusMatch && method === 'PUT') {
        const id = taskStatusMatch[1];
        const { status } = body || {};
        const r = this.taskSvc.setStatus(id, status);
        if (!r.ok) return json(res, 400, { error: r.reason });
        return json(res, 200, r.task);
      }

      const taskAssignMatch = path.match(/^\/tasks\/([^/]+)\/assign$/);
      if (taskAssignMatch && method === 'PUT') {
        const id = taskAssignMatch[1];
        const { userId } = body || {};
        if (!userId) return json(res, 400, { error: 'userId required' });
        const r = this.taskSvc.assign(id, userId);
        if (!r.ok) return json(res, 400, { error: r.reason });
        return json(res, 200, r.task);
      }

      // Comments
      if (path === '/comments' && method === 'GET') {
        const taskId = url.query['taskId'] as string | undefined;
        return json(res, 200, this.commentSvc.listComments(taskId ? { taskId } : undefined));
      }
      if (path === '/comments' && method === 'POST') {
        const { taskId, authorId, body: text } = body || {};
        if (!taskId || !authorId || !text) return json(res, 400, { error: 'taskId, authorId, body required' });
        // To allow notification service to notify task assignee, attach task snapshot
        const task = this.taskSvc.getTask(taskId);
        const comment = this.commentSvc.addComment(taskId, authorId, text);
        this.bus.publish('comment.added', { comment, task });
        return json(res, 201, comment);
      }

      const commentMatch = path.match(/^\/comments\/([^/]+)$/);
      if (commentMatch) {
        const id = commentMatch[1];
        if (method === 'GET') {
          const c = this.commentSvc.getComment(id);
          if (!c) return notFound(res);
          return json(res, 200, c);
        }
        if (method === 'DELETE') {
          const ok = this.commentSvc.deleteComment(id);
          if (!ok) return notFound(res);
          return json(res, 204, '');
        }
      }

      // Notifications
      if (path === '/notifications' && method === 'GET') {
        const userId = url.query['userId'] as string | undefined;
        return json(res, 200, this.notificationSvc.listNotifications(userId ? { userId } : undefined));
      }

      const notificationMatch = path.match(/^\/notifications\/([^/]+)\/read$/);
      if (notificationMatch && method === 'PUT') {
        const id = notificationMatch[1];
        const ok = this.notificationSvc.markRead(id);
        if (!ok) return notFound(res);
        return json(res, 200, { ok: true });
      }

      // nothing matched
      notFound(res);
    } catch (err: any) {
      console.error('handler error', err);
      json(res, 500, { error: 'internal' });
    }
  };

  createServer(port = 3000) {
    const srv = createServer(this.handler);
    srv.listen(port);
    return srv;
  }
}

